/* Horizonte: personal finance manager. Values are integer cents to avoid floating-point money math. */
const STORAGE_KEY='horizonte-finance-v1';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const todayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const cents=v=>Math.round((Number(v)||0)*100), money=(v,currency=state.settings.currency)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency,maximumFractionDigits:2}).format((Number(v)||0)/100);
const isoMonth=d=>String(d||todayISO()).slice(0,7), monthName=m=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(`${m}-02T12:00:00`));
const categories=[['Moradia','⌂'],['Alimentação','◉'],['Transporte','↗'],['Saúde','✚'],['Educação','▤'],['Compras','◇'],['Lazer','☼'],['Assinaturas','⟳'],['Salário','＄'],['Investimentos','↗'],['Outras receitas','＋'],['Contas','▧'],['Viagem','✈'],['Outros','•']];
function initialState(){const month=todayISO().slice(0,7),prev=new Date();prev.setMonth(prev.getMonth()-1);const pm=prev.toISOString().slice(0,7);return {version:1,isDemo:true,settings:{currency:'USD',dateFormat:'MM/DD/YYYY'},accounts:[{id:'acc-check',name:'Conta corrente',institution:'Conta principal',type:'checking',balance:250000,currency:'USD',color:'#397a58'},{id:'acc-save',name:'Reserva',institution:'Poupança',type:'savings',balance:800000,currency:'USD',color:'#648277'}],cards:[{id:'card-1',name:'Cartão principal',institution:'Horizonte',limit:300000,closingDay:22,dueDay:5,paymentAccountId:'acc-check',color:'#176b4c',active:true}],transactions:[
 {id:'t1',description:'Salário',amount:420000,type:'income',category:'Salário',date:`${month}-01`,accountId:'acc-check',paymentMethod:'Transferência',status:'received',recurrence:'monthly',fixed:true,notes:'Demonstração',createdAt:Date.now()},
 {id:'t2',description:'Aluguel',amount:145000,type:'expense',category:'Moradia',date:`${month}-03`,accountId:'acc-check',paymentMethod:'Transferência',status:'paid',recurrence:'monthly',fixed:true,createdAt:Date.now()},
 {id:'t3',description:'Supermercado',amount:6845,type:'expense',category:'Alimentação',date:`${month}-08`,accountId:'acc-check',paymentMethod:'Cartão de débito',status:'paid',recurrence:'one-time',fixed:false,createdAt:Date.now()},
 {id:'t4',description:'Conta de luz',amount:9200,type:'expense',category:'Contas',date:`${month}-26`,dueDate:`${month}-26`,accountId:'acc-check',paymentMethod:'Débito automático',status:'pending',recurrence:'monthly',fixed:true,createdAt:Date.now()},
 {id:'t5',description:'Restaurante',amount:5630,type:'expense',category:'Alimentação',date:`${month}-12`,cardId:'card-1',paymentMethod:'Cartão de crédito',status:'paid',recurrence:'one-time',fixed:false,createdAt:Date.now()},
 {id:'t6',description:'Academia',amount:3900,type:'expense',category:'Saúde',date:`${month}-28`,accountId:'acc-check',paymentMethod:'Débito automático',status:'pending',recurrence:'monthly',fixed:true,createdAt:Date.now()},
 {id:'t7',description:'Salário',amount:420000,type:'income',category:'Salário',date:`${pm}-01`,accountId:'acc-check',status:'received',recurrence:'monthly',fixed:true,createdAt:Date.now()},
 {id:'t8',description:'Aluguel',amount:145000,type:'expense',category:'Moradia',date:`${pm}-03`,accountId:'acc-check',status:'paid',recurrence:'monthly',fixed:true,createdAt:Date.now()},
 {id:'t9',description:'Mercado',amount:6320,type:'expense',category:'Alimentação',date:`${pm}-11`,accountId:'acc-check',status:'paid',recurrence:'one-time',fixed:false,createdAt:Date.now()}],budgets:[{id:'b1',category:'Alimentação',limit:50000},{id:'b2',category:'Moradia',limit:160000},{id:'b3',category:'Lazer',limit:15000},{id:'b4',category:'Transporte',limit:25000}],goals:[{id:'g1',name:'Reserva de emergência',target:1000000,saved:250000,dueDate:`${new Date().getFullYear()+1}-12-31`,monthlyContribution:75000,priority:'Alta',accountId:'acc-save'},{id:'g2',name:'Viagem de férias',target:300000,saved:65000,dueDate:`${new Date().getFullYear()+1}-08-01`,monthlyContribution:20000,priority:'Média'}],notifications:[],imports:[]}}
function emptyState(){const fresh=initialState();fresh.isDemo=false;fresh.accounts=[];fresh.cards=[];fresh.transactions=[];fresh.budgets=[];fresh.goals=[];fresh.notifications=[];fresh.imports=[];return fresh}
let state=emptyState();
const userStorageKey=user=>`${STORAGE_KEY}:${user.id}`;
const save=()=>{if(supabaseUser)localStorage.setItem(userStorageKey(supabaseUser),JSON.stringify(state))};
function loadUserState(user){try{const saved=localStorage.getItem(userStorageKey(user));state=saved?JSON.parse(saved):emptyState()}catch{state=emptyState()}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catIcon=name=>(categories.find(c=>c[0]===name)||['','•'])[1];
const selectedMonth=()=>$('#month-filter')?.value||todayISO().slice(0,7);
let currentPage='dashboard',txQuery='',txType='all',txStatus='all',txSort='date',historyFilter='all',editingId=null;
function txForMonth(m=selectedMonth()){return state.transactions.filter(t=>isoMonth(t.date)===m)}
function txTotals(list){return list.reduce((a,t)=>{if(t.type==='income'&&['received','paid'].includes(t.status))a.income+=t.amount;if(t.type==='expense'&&['paid','received'].includes(t.status))a.expense+=t.amount;if(t.type==='expense'&&t.status==='pending')a.pending+=t.amount;return a},{income:0,expense:0,pending:0})}
function availableBalance(){return state.accounts.filter(a=>(a.currency||state.settings.currency)===state.settings.currency).reduce((s,a)=>s+a.balance,0)}
function spentByCategory(cat,m=selectedMonth()){return txForMonth(m).filter(t=>t.category===cat&&t.type==='expense'&&['paid','received'].includes(t.status)).reduce((s,t)=>s+t.amount,0)}
function notify(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),3200)}
function addNotification(title,body,priority='normal',key=title){if(state.notifications.some(n=>n.key===key))return;state.notifications.unshift({id:uid(),title,body,priority,read:false,date:todayISO(),key});save()}
function generateAlerts(){const month=selectedMonth();for(const b of state.budgets){const used=spentByCategory(b.category,month),ratio=b.limit?used/b.limit:0;for(const threshold of [.5,.8,1])if(ratio>=threshold)addNotification(`Orçamento: ${b.category}`,`Você utilizou ${Math.round(ratio*100)}% do limite mensal de ${money(b.limit)}.`,ratio>=1?'high':'normal',`budget-${b.id}-${month}-${threshold}`)}for(const t of state.transactions.filter(t=>t.status==='pending'&&t.dueDate)){const diff=(new Date(`${t.dueDate}T12:00:00`)-new Date(`${todayISO()}T12:00:00`))/86400000;if(diff<0)addNotification('Despesa vencida',`${t.description}: ${money(t.amount)} venceu em ${formatDate(t.dueDate)}.`,'high',`due-${t.id}`);else if(diff<=5)addNotification('Vencimento próximo',`${t.description}: ${money(t.amount)} vence em ${formatDate(t.dueDate)}.`,'normal',`due-${t.id}`)}for(const c of state.cards){const used=cardUsed(c.id);if(c.limit&&used/c.limit>=.8)addNotification(`Limite de ${c.name}`,`${Math.round(used/c.limit*100)}% do limite utilizado.`,'high',`card-${c.id}-${month}`)}}
function formatDate(d){if(!d)return '—';const [y,m,day]=d.split('-');return state.settings.dateFormat==='DD/MM/YYYY'?`${day}/${m}/${y}`:`${m}/${day}/${y}`}
function pageName(p){return ({dashboard:'Visão geral',transactions:'Transações',accounts:'Contas',cards:'Cartões',budgets:'Orçamentos',goals:'Metas financeiras',reports:'Relatórios',history:'Histórico',settings:'Configurações'})[p]||'Visão geral'}
function pageHeader(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function monthPicker(){return `<label class="period-control">◷ <select id="month-filter">${Array.from({length:18},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const v=d.toISOString().slice(0,7);return `<option value="${v}" ${v===selectedMonth()?'selected':''}>${monthName(v)}</option>`}).join('')}</select></label>`}
function dashboard(){const m=selectedMonth(),total=txTotals(txForMonth(m)),saving=total.income-total.expense,rate=total.income?saving/total.income:0,days=new Date(`${m}-01T12:00:00`).getMonth()===new Date().getMonth()?new Date().getDate():31,remaining=total.income-total.expense-total.pending;const budgets=state.budgets.filter(b=>spentByCategory(b.category,m)>0).sort((a,b)=>spentByCategory(b.category,m)-spentByCategory(a.category,m)).slice(0,5);const next=state.transactions.filter(t=>t.status==='pending'&&t.dueDate).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,4);const recent=[...txForMonth(m)].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);const catTotal=budgets.reduce((s,b)=>s+spentByCategory(b.category,m),0);const palette=['#267252','#db9c73','#6a8ea0','#d6be77','#a68ac0','#cc7565'];const pieces=budgets.map((b,i)=>({name:b.category,value:spentByCategory(b.category,m),color:palette[i%palette.length]}));const deg=pieces.map(p=>p.value);let acc=0;const gradient=deg.length?`conic-gradient(${pieces.map(p=>{const start=acc;acc+=p.value/(catTotal||1)*360;return `${p.color} ${start}deg ${acc}deg`}).join(',')})`:'#edf1ed';return `${pageHeader('Seu dinheiro, com mais clareza.','Acompanhe suas finanças e construa o futuro que você quer.',`${monthPicker()}<button class="button button-primary button-small" data-action="new-tx">＋ Novo lançamento</button>`)}${state.isDemo?`<div class="demo-note"><span><b>Dados de demonstração</b> — personalize o espaço com seus lançamentos ou limpe os exemplos.</span><button data-action="clear-demo">Limpar demonstração</button></div>`:''}<section class="metrics-grid"><article class="metric-card"><div class="metric-top">Saldo total das contas <span class="metric-icon">▤</span></div><div class="metric-value">${money(availableBalance())}</div><div class="metric-foot">Em ${state.accounts.length} contas cadastradas</div></article><article class="metric-card"><div class="metric-top">Receitas do período <span class="metric-icon">↗</span></div><div class="metric-value">${money(total.income)}</div><div class="metric-foot">Valores recebidos em ${monthName(m)}</div></article><article class="metric-card"><div class="metric-top">Despesas do período <span class="metric-icon">↘</span></div><div class="metric-value">${money(total.expense)}</div><div class="metric-foot">${money(total.pending)} pendentes</div></article><article class="metric-card"><div class="metric-top">Disponível este mês <span class="metric-icon">◉</span></div><div class="metric-value">${money(remaining)}</div><div class="metric-foot">${Math.max(0,new Date(`${m}-01T12:00:00`).getMonth()===new Date().getMonth()?new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()-days:0)} dias restantes · saldo do mês − pendências</div></article></section><section class="dashboard-grid"><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Receitas e despesas</h2><p class="panel-subtitle">Visão mensal dos últimos seis meses</p></div><div class="legend"><span><i></i> Receitas</span><span><i class="coral"></i> Despesas</span></div></div><div class="chart-wrap"><canvas id="trend-chart" aria-label="Gráfico de receitas e despesas"></canvas></div></article><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Gastos por categoria</h2><p class="panel-subtitle">Distribuição das despesas em ${monthName(m)}</p></div></div><div class="donut-wrap"><div class="donut" style="background:${gradient}"><div class="donut-center"><b>${money(catTotal)}</b><small>total em categorias</small></div></div><div class="category-legend">${pieces.length?pieces.slice(0,5).map(p=>`<div class="category-row"><i class="category-dot" style="background:${p.color}"></i><span>${esc(p.name)}</span><b>${money(p.value)}</b></div>`).join(''):'<span class="muted">Sem despesas no período</span>'}</div></div></article></section><section class="lower-grid"><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Movimentações recentes</h2><p class="panel-subtitle">Seus últimos lançamentos</p></div><button class="inline-action" data-page="transactions">Ver todas →</button></div><div class="transaction-list">${recent.length?recent.map(t=>`<div class="transaction-item"><div class="transaction-icon">${catIcon(t.category)}</div><div><div class="transaction-name">${esc(t.description)}</div><div class="transaction-meta">${esc(t.category)} · ${formatDate(t.date)}</div></div><div class="transaction-amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'} ${money(t.amount)}</div><div class="transaction-status">${statusName(t.status)}</div></div>`).join(''):'<div class="empty-state"><div class="empty-icon">↕</div><b>Nenhuma movimentação neste período</b><p>Adicione um lançamento para acompanhar seu mês.</p></div>'}</div></article><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Próximos vencimentos</h2><p class="panel-subtitle">Despesas pendentes e contas a pagar</p></div><span class="muted">${next.length} próximas</span></div><div class="due-list">${next.length?next.map(t=>`<div class="due-row"><div class="due-date"><b>${t.dueDate.slice(8,10)}</b>${new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(`${t.dueDate}T12:00:00`)).toUpperCase()}</div><div class="due-description">${esc(t.description)}<small>${esc(t.category)}</small></div><div class="due-amount">${money(t.amount)}</div></div>`).join(''):'<div class="empty-state"><div class="empty-icon">✓</div><b>Tudo em dia</b><p>Vencimentos pendentes aparecerão aqui.</p></div>'}</div></article></section><section class="metrics-grid" style="margin-top:15px"><article class="metric-card"><div class="metric-top">Economizado no período <span class="metric-icon">✳</span></div><div class="metric-value ${saving<0?'negative':'positive'}">${money(saving)}</div><div class="metric-foot">${(rate*100).toFixed(1)}% de taxa de poupança</div></article><article class="metric-card"><div class="metric-top">Despesas comprometidas <span class="metric-icon">◷</span></div><div class="metric-value">${money(total.pending)}</div><div class="metric-foot">Lançamentos pendentes neste mês</div></article><article class="metric-card"><div class="metric-top">Metas financeiras <span class="metric-icon">◎</span></div><div class="metric-value">${state.goals.length}</div><div class="metric-foot">${state.goals.length?Math.round(state.goals.reduce((s,g)=>s+g.saved/Math.max(1,g.target),0)/state.goals.length*100):0}% de progresso médio</div></article><article class="metric-card"><div class="metric-top">Limite de cartões usado <span class="metric-icon">▭</span></div><div class="metric-value">${money(state.cards.reduce((s,c)=>s+cardUsed(c.id),0))}</div><div class="metric-foot">Não incluído no saldo disponível</div></article></section>`}
function statusName(s){return ({pending:'Pendente',paid:'Pago',received:'Recebido',forecast:'Previsto'})[s]||s}
function transactionPage(history=false){const list=[...state.transactions].filter(t=>(!historyFilter||historyFilter==='all'||t.type===historyFilter)&&(!txQuery||`${t.description} ${t.category} ${t.notes||''}`.toLowerCase().includes(txQuery.toLowerCase()))&&(txType==='all'||t.type===txType)&&(txStatus==='all'||t.status===txStatus)).sort((a,b)=>txSort==='amount'?b.amount-a.amount:b.date.localeCompare(a.date));const actions=`<button class="button button-secondary button-small" data-action="import-csv">⇧ Importar CSV</button><button class="button button-secondary button-small" data-action="export-csv">⇩ Exportar CSV</button><button class="button button-primary button-small" data-action="new-tx">＋ Nova transação</button>`;return `${pageHeader(history?'Seu histórico financeiro':'Transações','Consulte, filtre e organize todas as suas movimentações.',actions)}${history?`<div class="summary-cards"><div class="summary-box"><span>Movimentações registradas</span><b>${state.transactions.length}</b></div><div class="summary-box"><span>Período acompanhado</span><b>${state.transactions.length?formatDate([...state.transactions].sort((a,b)=>a.date.localeCompare(b.date))[0].date)+' – '+formatDate(todayISO()):'—'}</b></div><div class="summary-box"><span>Alterações e importações</span><b>${state.imports.length} importações</b></div></div>`:''}<section class="data-panel"><div class="table-toolbar"><label class="search-field"><span>⌕</span><input class="input" id="tx-search" value="${esc(txQuery)}" placeholder="Buscar por descrição ou categoria"></label><select class="select filter-select" id="tx-type"><option value="all">Todos os tipos</option><option value="income" ${txType==='income'?'selected':''}>Receitas</option><option value="expense" ${txType==='expense'?'selected':''}>Despesas</option></select><select class="select filter-select" id="tx-status"><option value="all">Todos os status</option>${['paid','received','pending','forecast'].map(s=>`<option value="${s}" ${txStatus===s?'selected':''}>${statusName(s)}</option>`).join('')}</select><select class="select filter-select" id="tx-sort"><option value="date">Mais recentes</option><option value="amount" ${txSort==='amount'?'selected':''}>Maior valor</option></select><span class="table-count">${list.length} registros</span></div>${list.length?`<div class="table-scroll"><table><thead><tr><th>Descrição</th><th>Categoria</th><th>Data</th><th>Conta / cartão</th><th>Tipo</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody>${list.map(t=>{const linked=state.accounts.find(a=>a.id===t.accountId)?.name||state.cards.find(c=>c.id===t.cardId)?.name||'—';return `<tr><td><strong>${esc(t.description)}</strong>${t.recurrence&&t.recurrence!=='one-time'?`<div class="recurring-badge">↻ ${recurrenceName(t.recurrence)}</div>`:''}</td><td>${esc(t.category)}</td><td>${formatDate(t.date)}${t.dueDate?`<div class="muted">Vence ${formatDate(t.dueDate)}</div>`:''}</td><td>${esc(linked)}</td><td><span class="type-pill ${t.type==='expense'?'expense':''}">${t.type==='income'?'Receita':'Despesa'}</span></td><td><span class="status-pill ${t.status==='pending'?'pending':''}">${statusName(t.status)}</span></td><td><strong class="${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'} ${money(t.amount)}</strong></td><td><div class="row-actions">${t.status==='pending'?`<button title="Registrar pagamento/recebimento" data-action="settle-tx" data-id="${t.id}">✓</button>`:''}<button title="Editar" data-action="edit-tx" data-id="${t.id}">✎</button><button title="Excluir" data-action="delete-tx" data-id="${t.id}">×</button></div></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">↕</div><b>${txQuery?'Nenhum resultado encontrado':'Sua jornada começa aqui'}</b><p>${txQuery?'Tente ajustar a busca ou os filtros.':'Adicione uma transação para acompanhar sua vida financeira.'}</p><button class="button button-secondary button-small" data-action="new-tx">＋ Adicionar transação</button></div>`}</section>`}
function recurrenceName(r){return ({weekly:'Semanal',monthly:'Mensal',annual:'Anual'})[r]||'Única'}
function accountsPage(){const total=availableBalance();return `${pageHeader('Suas contas','Acompanhe saldos e mantenha suas contas organizadas.',`<button class="button button-primary button-small" data-action="new-account">＋ Adicionar conta</button>`)}<div class="summary-cards"><div class="summary-box"><span>Saldo total</span><b>${money(total)}</b></div><div class="summary-box"><span>Contas cadastradas</span><b>${state.accounts.length}</b></div><div class="summary-box"><span>Contas de reserva</span><b>${state.accounts.filter(a=>a.type==='savings').length}</b></div></div><div class="account-grid">${state.accounts.length?state.accounts.map(a=>`<article class="panel account-card"><div class="account-head"><span class="account-symbol">${a.type==='savings'?'◈':'▤'}</span><button class="row-actions" data-action="edit-account" data-id="${a.id}">✎</button></div><div class="account-balance">${money(a.balance,a.currency)}</div><div class="muted">${esc(a.name)} · ${esc(a.institution||accountType(a.type))}</div><div class="account-actions"><span class="muted">${accountType(a.type)}</span><button class="inline-action" data-action="account-history" data-id="${a.id}">Ver movimentações →</button></div></article>`).join(''):`<div class="panel empty-state"><div class="empty-icon">▤</div><b>Nenhuma conta cadastrada</b><p>Adicione uma conta para controlar seus saldos.</p></div>`}</div><div class="notice" style="margin-top:16px"><strong>Saldo atual x saldo projetado:</strong> saldo da conta usa o saldo inicial ajustado por movimentações pagas. Valores previstos e limites de cartão ficam separados.</div>`}
function accountType(t){return ({checking:'Conta corrente',savings:'Poupança / reserva',cash:'Dinheiro em espécie',investment:'Investimentos'})[t]||t}
function cardUsed(id){return state.transactions.filter(t=>t.cardId===id&&t.type==='expense'&&t.status!=='forecast').reduce((s,t)=>s+t.amount,0)}
function cardsPage(){return `${pageHeader('Seus cartões','Gerencie limites, compras e compromissos do cartão.',`<button class="button button-secondary button-small" data-action="import-csv">⇧ Importar CSV</button><button class="button button-primary button-small" data-action="new-card">＋ Adicionar cartão</button>`)}<div class="notice"><strong>Compras e faturas:</strong> compras lançadas no cartão contam como despesas. Registrar o pagamento da fatura como transferência evita contabilizar essas compras duas vezes.</div><div class="card-grid">${state.cards.length?state.cards.map((c,i)=>{const used=cardUsed(c.id),pct=c.limit?used/c.limit:0;return `<article class="panel" style="padding:13px"><div class="credit-card ${i%2?'alt':''}" style="background:linear-gradient(130deg,${esc(c.color||'#176b4c')},#354b42)"><div class="card-bank">${esc(c.institution||'Instituição financeira')}</div><div class="card-name">${esc(c.name)}</div><div class="card-number">•••• &nbsp; •••• &nbsp; •••• &nbsp; 2048</div><div class="card-bottom"><span>FECHAMENTO · DIA ${c.closingDay}</span><span>VENCIMENTO · DIA ${c.dueDay}</span></div></div><div class="card-limit"><div class="card-summary"><span>Limite utilizado</span><b>${money(used)} / ${money(c.limit)}</b></div><div class="progress-track"><div class="progress-fill ${pct>.9?'over':pct>.7?'warning':''}" style="width:${Math.min(100,pct*100)}%"></div></div><div class="card-summary muted"><span>${Math.round(pct*100)}% utilizado</span><span>${money(Math.max(0,c.limit-used))} disponível</span></div></div><div class="account-actions"><button class="inline-action" data-action="new-card-purchase" data-id="${c.id}">＋ Registrar compra</button><button class="inline-action" data-action="edit-card" data-id="${c.id}">Editar cartão</button></div></article>`}).join(''):`<div class="panel empty-state"><div class="empty-icon">▭</div><b>Nenhum cartão cadastrado</b><p>Adicione um cartão para acompanhar seus limites.</p></div>`}</div><section class="panel" style="margin-top:15px"><div class="panel-heading"><div><h2 class="panel-title">Compras recentes no cartão</h2><p class="panel-subtitle">Lançamentos relacionados aos cartões cadastrados</p></div></div><div class="table-scroll"><table><thead><tr><th>Descrição</th><th>Cartão</th><th>Data</th><th>Categoria</th><th>Valor</th></tr></thead><tbody>${state.transactions.filter(t=>t.cardId).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(t=>`<tr><td><strong>${esc(t.description)}</strong></td><td>${esc(state.cards.find(c=>c.id===t.cardId)?.name||'—')}</td><td>${formatDate(t.date)}</td><td>${esc(t.category)}</td><td><strong>${money(t.amount)}</strong></td></tr>`).join('')||'<tr><td colspan="5" class="muted">Ainda não há compras registradas em cartão.</td></tr>'}</tbody></table></div></section>`}
function budgetsPage(){const m=selectedMonth();return `${pageHeader('Orçamento mensal','Defina limites e acompanhe seus gastos por categoria.',`${monthPicker()}<button class="button button-primary button-small" data-action="new-budget">＋ Novo limite</button>`)}<div class="notice">Os gastos consideram despesas pagas e recebidas no mês selecionado. Alertas são criados ao atingir 50%, 80% e 100% do limite.</div><div class="budget-grid">${state.budgets.length?state.budgets.map(b=>{const used=spentByCategory(b.category,m),pct=b.limit?used/b.limit:0,remaining=b.limit-used;return `<article class="panel budget-card"><div class="budget-top"><div class="category-badge"><span class="badge-icon">${catIcon(b.category)}</span>${esc(b.category)}</div><div class="row-actions"><button data-action="edit-budget" data-id="${b.id}">✎</button><button data-action="delete-budget" data-id="${b.id}">×</button></div></div><div class="budget-amount">${money(used)} <span class="muted">de ${money(b.limit)}</span></div><div class="progress-track"><div class="progress-fill ${pct>=1?'over':pct>=.8?'warning':''}" style="width:${Math.min(100,pct*100)}%"></div></div><div class="budget-foot"><span>${Math.round(pct*100)}% utilizado</span><span class="${remaining<0?'negative':''}">${remaining>=0?money(remaining)+' restantes':money(-remaining)+' acima do limite'}</span></div></article>`}).join(''):`<div class="panel empty-state"><div class="empty-icon">◷</div><b>Nenhum orçamento definido</b><p>Crie limites por categoria para acompanhar seus planos.</p></div>`}</div>`}
function goalMetrics(g){const left=Math.max(0,g.target-g.saved),months=Math.max(1,Math.ceil((new Date(`${g.dueDate}T12:00:00`)-new Date(`${todayISO()}T12:00:00`))/(1000*60*60*24*30.4375))),needed=Math.ceil(left/months),weekly=Math.ceil(left/(months*4.345)),onTrack=g.monthlyContribution>=needed;return {left,months,needed,weekly,onTrack,pct:g.target?Math.min(100,g.saved/g.target*100):0}}
function goalsPage(){return `${pageHeader('Metas financeiras','Transforme objetivos em planos possíveis.',`<button class="button button-primary button-small" data-action="new-goal">＋ Nova meta</button>`)}<div class="notice">Valores mensais e semanais mostram o ritmo estimado para alcançar o prazo. São cenários indicativos, não garantias.</div><div class="goal-grid">${state.goals.length?state.goals.map(g=>{const x=goalMetrics(g);return `<article class="panel goal-card"><div class="goal-top"><div class="category-badge"><span class="badge-icon">◎</span>${esc(g.name)}</div><div class="row-actions"><button data-action="contribute-goal" data-id="${g.id}" title="Registrar contribuição">＋</button><button data-action="edit-goal" data-id="${g.id}">✎</button><button data-action="delete-goal" data-id="${g.id}">×</button></div></div><div class="goal-target">${money(g.target)}</div><div class="muted">objetivo até ${formatDate(g.dueDate)}</div><div class="progress-track" style="margin-top:16px"><div class="progress-fill" style="width:${x.pct}%"></div></div><div class="goal-bottom"><span>${money(g.saved)} guardados (${Math.round(x.pct)}%)</span><span>${money(x.left)} restantes</span></div><div class="goal-needed">${x.onTrack?'✓ No ritmo planejado':'! Ajuste a contribuição mensal'} · ${money(x.needed)}/mês · ${money(x.weekly)}/semana</div></article>`}).join(''):`<div class="panel empty-state"><div class="empty-icon">◎</div><b>Qual é o seu próximo objetivo?</b><p>Crie uma meta para planejar sua economia.</p></div>`}</div>`}
function reportsPage(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);return d.toISOString().slice(0,7)}).reverse();const byMonth=months.map(m=>({month:m,...txTotals(txForMonth(m))}));const categoriesMap={};for(const t of txForMonth())if(t.type==='expense'&&['paid','received'].includes(t.status))categoriesMap[t.category]=(categoriesMap[t.category]||0)+t.amount;const max=Math.max(1,...Object.values(categoriesMap));const current=txTotals(txForMonth()),savings=current.income-current.expense;return `${pageHeader('Relatórios','Entenda suas tendências e tome decisões com confiança.',`<button class="button button-secondary button-small" data-action="export-csv">⇩ Exportar transações</button><button class="button button-secondary button-small" data-action="export-report">⇩ Resumo CSV</button>`)}<div class="summary-cards"><div class="summary-box"><span>Receitas · ${monthName(selectedMonth())}</span><b class="positive">${money(current.income)}</b></div><div class="summary-box"><span>Despesas · ${monthName(selectedMonth())}</span><b>${money(current.expense)}</b></div><div class="summary-box"><span>Saldo do período / taxa de economia</span><b class="${savings<0?'negative':'positive'}">${money(savings)} · ${current.income?(savings/current.income*100).toFixed(1):0}%</b></div></div><div class="report-grid"><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Comparativo mensal</h2><p class="panel-subtitle">Receitas e despesas dos últimos seis meses</p></div></div><div class="bar-list">${byMonth.map(x=>{const scale=Math.max(1,...byMonth.map(y=>Math.max(y.income,y.expense)));return `<div class="bar-item"><span class="bar-label">${monthName(x.month).split(' de ')[0]} ${x.month.slice(2,4)}</span><span style="display:grid;gap:3px"><span class="bar-track"><span class="bar-fill" style="width:${x.income/scale*100}%;display:block"></span></span><span class="bar-track"><span class="bar-fill" style="width:${x.expense/scale*100}%;display:block;background:#dfa18d"></span></span></span><span class="bar-value">${money(x.income-x.expense)}</span></div>`}).join('')}</div><div class="legend" style="margin-top:14px"><span><i></i> Receitas</span><span><i class="coral"></i> Despesas</span></div></article><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Gastos por categoria</h2><p class="panel-subtitle">Despesas realizadas neste período</p></div></div><div class="bar-list">${Object.entries(categoriesMap).sort((a,b)=>b[1]-a[1]).map(([n,v])=>`<div class="bar-item"><span class="bar-label">${esc(n)}</span><span class="bar-track"><span class="bar-fill" style="width:${v/max*100}%;display:block"></span></span><span class="bar-value">${money(v)}</span></div>`).join('')||'<div class="empty-state">Sem despesas registradas neste mês.</div>'}</div></article><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Despesas fixas e variáveis</h2><p class="panel-subtitle">Classificação dos lançamentos do período</p></div></div><div class="summary-cards" style="grid-template-columns:1fr 1fr;margin:0"><div class="summary-box"><span>Fixas</span><b>${money(txForMonth().filter(t=>t.type==='expense'&&t.fixed&&t.status==='paid').reduce((s,t)=>s+t.amount,0))}</b></div><div class="summary-box"><span>Variáveis</span><b>${money(txForMonth().filter(t=>t.type==='expense'&&!t.fixed&&t.status==='paid').reduce((s,t)=>s+t.amount,0))}</b></div></div></article><article class="panel"><div class="panel-heading"><div><h2 class="panel-title">Compromissos futuros</h2><p class="panel-subtitle">Despesas pendentes por mês de vencimento</p></div></div><div class="bar-list">${Array.from({length:3},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+i);const m=d.toISOString().slice(0,7);const val=state.transactions.filter(t=>t.type==='expense'&&t.status==='pending'&&isoMonth(t.dueDate||t.date)===m).reduce((s,t)=>s+t.amount,0);return `<div class="bar-item"><span class="bar-label">${monthName(m)}</span><span class="bar-track"><span class="bar-fill" style="width:${Math.min(100,val/Math.max(1,...state.transactions.map(t=>t.amount))*100)}%;display:block;background:#8aa998"></span></span><span class="bar-value">${money(val)}</span></div>`}).join('')}</div></article></div>`}
function settingsPage(){return `${pageHeader('Configurações','Personalize seu espaço financeiro e gerencie seus dados.')}<div class="settings-grid"><section class="panel settings-panel"><h3>Preferências regionais</h3><p class="field-help" id="space-settings-status" role="status">${esc(spaceSettingsStatus)}</p><div class="settings-row"><span>Moeda principal<br><small class="muted">Todos os saldos usam esta moeda.</small></span><select class="select" id="settings-currency"><option value="USD" ${state.settings.currency==='USD'?'selected':''}>USD · Dólar</option><option value="BRL" ${state.settings.currency==='BRL'?'selected':''}>BRL · Real</option><option value="EUR" ${state.settings.currency==='EUR'?'selected':''}>EUR · Euro</option></select></div><div class="settings-row"><span>Formato de data</span><select class="select" id="settings-date"><option value="MM/DD/YYYY" ${state.settings.dateFormat==='MM/DD/YYYY'?'selected':''}>MM/DD/YYYY</option><option value="DD/MM/YYYY" ${state.settings.dateFormat==='DD/MM/YYYY'?'selected':''}>DD/MM/YYYY</option></select></div></section><section class="panel settings-panel"><h3>Dados e privacidade</h3><div class="settings-row"><span><b>Dados financeiros locais</b><br><small class="muted">Contas e lançamentos ficam neste navegador.</small></span><span class="status-pill">Local</span></div><div class="settings-row"><span>Exportar cópia dos dados<br><small class="muted">Baixe um arquivo JSON para backup.</small></span><button class="button button-secondary button-small" data-action="backup">Exportar</button></div><div class="settings-row"><span>Restaurar dados de backup</span><button class="button button-secondary button-small" data-action="restore">Importar JSON</button></div><div class="settings-row"><span>Dados de demonstração</span><button class="button button-danger button-small" data-action="clear-demo">Limpar exemplos</button></div></section></div><div class="notice" style="margin-top:15px"><strong>Sobre os dados:</strong> moeda e formato de data são salvos nas preferências do espaço no Supabase. Contas, lançamentos, cartões, orçamentos e metas continuam locais e não são sincronizados; não guarde credenciais bancárias ou números completos de cartões.</div>`}
let supabaseUser=null,supabaseMemberships=[],selectedSpaceId='';
let spaceSettingsStatus='Entre em um espaço financeiro para salvar estas preferências no Supabase.';
function setSpaceSettingsStatus(message,isError=false){spaceSettingsStatus=message;const el=$('#space-settings-status');if(el){el.textContent=message;el.style.color=isError?'#a34e3f':''}}
async function loadSpaceSettings(){const client=window.supabaseClient;if(!supabaseUser||!selectedSpaceId||!client)return;setSpaceSettingsStatus('Carregando preferências do espaço no Supabase…');const {data,error}=await client.from('finance_space_preferences').select('currency,date_format').eq('space_id',selectedSpaceId).maybeSingle();if(error){const missing=error.code==='42P01'||error.code==='PGRST205';setSpaceSettingsStatus(missing?'Falta criar a tabela de preferências. Execute a migration indicada no projeto.':`Não foi possível ler as preferências (${error.code||'erro'}).`,true);return}if(data){state.settings={...state.settings,currency:data.currency,dateFormat:data.date_format};save();setSpaceSettingsStatus('Preferências carregadas do Supabase.');return}await persistSpaceSettings('Preferências iniciais salvas no Supabase.')}
async function persistSpaceSettings(successMessage='Preferências salvas no Supabase.'){const client=window.supabaseClient,spaceId=selectedSpaceId;if(!supabaseUser||!spaceId||!client){setSpaceSettingsStatus('Selecione um espaço financeiro para salvar no Supabase.',true);return false}const settings={space_id:spaceId,currency:state.settings.currency,date_format:state.settings.dateFormat,updated_at:new Date().toISOString()};setSpaceSettingsStatus('Salvando no Supabase…');const {error}=await client.from('finance_space_preferences').upsert(settings,{onConflict:'space_id'});if(error){const missing=error.code==='42P01'||error.code==='PGRST205';setSpaceSettingsStatus(missing?'A tabela ainda não existe. Execute supabase/migrations/202610270003_space_preferences.sql no SQL Editor.':`Falha ao salvar (${error.code||'erro'}): ${error.message}`,true);return false}setSpaceSettingsStatus(successMessage);return true}
function authPanel(){const client=window.supabaseClient;const sessionText=!client?'Biblioteca Supabase indisponível. Confira a conexão e recarregue.':supabaseUser?`Sessão ativa: ${esc(supabaseUser.email||supabaseUser.id)}`:'Sem sessão autenticada.';const spaces=supabaseMemberships.map(m=>({label:`${m.space_name||m.space_id} · ${m.role}`,value:m.space_id}));return `<section class="panel settings-panel" style="margin-bottom:15px"><h3>Conexão e acesso ao Supabase</h3><div class="settings-row"><span><b>Banco de dados</b><br><small class="muted" id="supabase-db-status">Pronto para verificar a tabela de diagnóstico.</small></span><button class="button button-secondary button-small" data-action="supabase-test">Testar conexão</button></div><div class="settings-row"><span><b>Autenticação</b><br><small class="muted" id="supabase-auth-status">${sessionText}</small></span>${supabaseUser?'<button class="button button-secondary button-small" data-action="supabase-logout">Sair</button>':''}</div>${supabaseUser?`${supabaseMemberships.length?`<div class="settings-row"><span>Espaço ativo</span><select class="select" id="supabase-space-select">${options(spaces,selectedSpaceId,x=>x.label,x=>x.value)}</select></div>`:'<div class="notice">Esta conta ainda não participa de um espaço financeiro. Vamos criar/vincular um espaço em uma etapa seguinte.</div>'}`:`<div class="form-grid" style="margin-top:14px"><label class="field"><span class="field-label">E-mail</span><input class="input" id="supabase-email" type="email" autocomplete="email" value="${esc(authEmailDraft)}" required></label><label class="field"><span class="field-label">Senha</span><input class="input" id="supabase-password" type="password" autocomplete="current-password" minlength="8" required></label></div><div class="heading-actions" style="margin-top:12px"><button class="button button-primary button-small" data-action="supabase-login">Entrar</button><button class="button button-secondary button-small" data-action="supabase-signup">Criar conta</button></div>`}<p class="field-help" style="margin-top:13px">A sessão é gerenciada pelo Supabase. Os dados financeiros demonstrativos continuam locais e ainda não são enviados ao banco.</p></section>`}
function signedInPanel(){const spaces=supabaseMemberships.map(m=>({label:`${m.space_name||m.space_id} · ${m.role}`,value:m.space_id}));return `<section class="panel settings-panel" style="margin-bottom:15px"><h3>Conta e conexão</h3><div class="settings-row"><span><b>Banco de dados</b><br><small class="muted" id="supabase-db-status">Pronto para verificar a tabela de diagnóstico.</small></span><button class="button button-secondary button-small" data-action="supabase-test">Testar conexão</button></div><div class="settings-row"><span><b>Sessão ativa</b><br><small class="muted">${esc(supabaseUser.email||supabaseUser.id)}</small></span><button class="button button-secondary button-small" data-action="supabase-logout">Sair</button></div>${supabaseMemberships.length?`<div class="settings-row"><span>Espaço ativo</span><select class="select" id="supabase-space-select">${options(spaces,selectedSpaceId,x=>x.label,x=>x.value)}</select></div>`:'<div class="notice">Esta conta ainda não participa de um espaço financeiro. Vamos criar/vincular um espaço em uma etapa seguinte.</div>'}<p class="field-help" style="margin-top:13px">Os dados financeiros ainda ficam neste navegador; eles não são sincronizados com o banco.</p></section>`}
let authMessage='',authView='login',authEmailDraft='';
function authGateMarkup(){const header=`<div class="auth-brand"><span class="brand-mark">h.</span><span>horizonte<small>FINANÇAS PESSOAIS</small></span></div>`;const notice=authMessage?`<div class="notice" role="status">${esc(authMessage)}</div>`:'';if(authView==='recovery')return `<main class="auth-gate-content"><section class="auth-card">${header}<div class="auth-intro"><h1>Recuperar acesso</h1><p>Informe seu e-mail e enviaremos um link para redefinir a senha.</p></div>${notice}<div class="auth-fields"><label class="field"><span class="field-label">E-mail</span><input class="input" id="supabase-email" type="email" autocomplete="email" value="${esc(authEmailDraft)}" required></label></div><div class="auth-actions"><button class="button button-primary" data-action="supabase-send-reset">Enviar link de recuperação</button><button class="button button-secondary" data-action="auth-back">Voltar para entrar</button></div></section></main>`;if(authView==='update-password')return `<main class="auth-gate-content"><section class="auth-card">${header}<div class="auth-intro"><h1>Defina uma nova senha</h1><p>Escolha e confirme sua nova senha para continuar.</p></div>${notice}<div class="auth-fields"><label class="field"><span class="field-label">Nova senha</span><input class="input" id="recovery-password" type="password" autocomplete="new-password" minlength="8" required></label><label class="field"><span class="field-label">Confirmar nova senha</span><input class="input" id="recovery-password-confirm" type="password" autocomplete="new-password" minlength="8" required></label></div><div class="auth-actions"><button class="button button-primary" data-action="supabase-update-password">Salvar nova senha</button></div></section></main>`;return `<main class="auth-gate-content"><section class="auth-card">${header}<div class="auth-intro"><p class="side-label">ESPAÇO PESSOAL</p><h1>Entre para continuar</h1><p>Acesse sua área financeira com seu e-mail e senha.</p></div>${notice}<div class="auth-fields"><label class="field"><span class="field-label">Usuário (e-mail)</span><input class="input" id="supabase-email" type="email" autocomplete="username" value="${esc(authEmailDraft)}" required></label><label class="field"><span class="field-label">Senha</span><input class="input" id="supabase-password" type="password" autocomplete="current-password" minlength="8" required></label></div><div class="auth-actions"><button class="button button-primary" data-action="supabase-login">Entrar</button><button class="button button-secondary" data-action="supabase-signup">Criar conta</button><button class="auth-link" data-action="auth-forgot">Esqueci minha senha</button></div><p class="auth-footnote">Suas informações financeiras só aparecem depois que você entrar.</p></section></main>`}
const localSettingsPage=settingsPage;
settingsPage=()=>signedInPanel()+localSettingsPage();
async function loadSupabaseMemberships(user){const client=window.supabaseClient;const {data,error}=await client.from('finance_space_members').select('space_id,role').eq('user_id',user.id);if(error)throw error;const members=data||[];if(!members.length){supabaseMemberships=[];selectedSpaceId='';return}const ids=members.map(x=>x.space_id);const {data:spaces,error:spaceError}=await client.from('finance_spaces').select('id,name').in('id',ids);if(spaceError)throw spaceError;supabaseMemberships=members.map(m=>({...m,space_name:(spaces||[]).find(s=>s.id===m.space_id)?.name||m.space_id}));if(!supabaseMemberships.some(m=>m.space_id===selectedSpaceId))selectedSpaceId=supabaseMemberships[0].space_id}
async function testSupabaseConnection(){const status=$('#supabase-db-status'),client=window.supabaseClient;if(!client){notify('Cliente Supabase não carregado.','error');return}if(status)status.textContent='Consultando a tabela connection_check…';const {data,error}=await client.from('connection_check').select('id,checked_at').eq('id','horizonte-ready').maybeSingle();if(error){if(status)status.textContent=`Falha (${error.code||'sem código'}): ${error.message}`;notify('Não foi possível consultar a tabela de diagnóstico.','error');return}if(status)status.textContent=data?`Conectado · verificação do banco ${formatDate(data.checked_at.slice(0,10))}`:'Conectado, mas o marcador não foi encontrado.';notify(data?'Conexão com o banco confirmada.':'A tabela respondeu sem o marcador esperado.',data?'':'error')}
async function authenticateSupabase(mode){const client=window.supabaseClient;if(!client)return notify('Cliente Supabase não carregado.','error');const email=$('#supabase-email')?.value.trim(),password=$('#supabase-password')?.value;if(!email||!password)return notify('Preencha e-mail e senha.','error');try{const result=mode==='signup'?await client.auth.signUp({email,password}):await client.auth.signInWithPassword({email,password});if(result.error)throw result.error;if(mode==='signup'&&!result.data.session){authMessage='Conta criada. Confirme o endereço de e-mail e volte para entrar.';render();return}supabaseUser=result.data.user||result.data.session?.user||null;if(supabaseUser){loadUserState(supabaseUser);try{await loadSupabaseMemberships(supabaseUser);await loadSpaceSettings()}catch(error){notify(`Espaços: ${error.message||'falha ao carregar'}`,'error')}}authMessage='';const pass=$('#supabase-password');if(pass)pass.value='';render();notify(mode==='signup'?'Conta criada e sessão iniciada.':'Login concluído.')}catch(error){authMessage=error.message||'Não foi possível autenticar.';render();notify(`Autenticação: ${authMessage}`,'error')}}
async function requestPasswordReset(){const client=window.supabaseClient,email=$('#supabase-email')?.value.trim();if(!client)return notify('Cliente Supabase não carregado.','error');if(!email){authMessage='Informe seu e-mail para receber o link de recuperação.';authView='recovery';render();return}try{const redirectTo=/^https?:$/.test(window.location.protocol)?`${window.location.origin}${window.location.pathname}`:undefined;const result=redirectTo?await client.auth.resetPasswordForEmail(email,{redirectTo}):await client.auth.resetPasswordForEmail(email);if(result.error)throw result.error;authMessage='Se houver uma conta para esse e-mail, enviaremos as instruções de recuperação.';authView='recovery';render()}catch(error){authMessage=error.message||'Não foi possível solicitar a recuperação.';authView='recovery';render()}}
async function updateRecoveredPassword(){const client=window.supabaseClient,password=$('#recovery-password')?.value,confirmation=$('#recovery-password-confirm')?.value;if(!client)return notify('Cliente Supabase não carregado.','error');if(!password||password.length<8){authMessage='A nova senha precisa ter pelo menos 8 caracteres.';render();return}if(password!==confirmation){authMessage='As senhas não coincidem.';render();return}const {error}=await client.auth.updateUser({password});if(error){authMessage=error.message||'Não foi possível atualizar a senha.';render();return}const {error:signOutError}=await client.auth.signOut();if(signOutError){authMessage='Senha atualizada, mas não foi possível encerrar a sessão. Recarregue o app.';render();return}supabaseUser=null;supabaseMemberships=[];selectedSpaceId='';state=emptyState();authView='login';authMessage='Senha atualizada. Entre com sua nova senha.';if(window.location.hash)history.replaceState(null,document.title,window.location.pathname+window.location.search);render()}
async function signOutSupabase(){const client=window.supabaseClient;if(!client)return;save();const {error}=await client.auth.signOut();if(error)return notify(`Não foi possível sair: ${error.message}`,'error');supabaseUser=null;supabaseMemberships=[];selectedSpaceId='';state=emptyState();authView='login';render();notify('Sessão encerrada.')}
async function restoreSupabaseSession(){const client=window.supabaseClient;if(!client)return;const {data,error}=await client.auth.getSession();if(error)return;if(window.location.hash.includes('type=recovery')){authView='update-password';authMessage='';supabaseUser=data.session?.user||null;render();return}if(data.session?.user){supabaseUser=data.session.user;loadUserState(supabaseUser);try{await loadSupabaseMemberships(supabaseUser);await loadSpaceSettings()}catch(e){notify(`Espaços: ${e.message||'falha ao carregar'}`,'error')}}render()}
function render(){const gate=$('#auth-gate');if(!supabaseUser||authView==='update-password'){document.body.classList.remove('authenticated');document.body.classList.add('auth-required');if(gate){gate.hidden=false;gate.innerHTML=authGateMarkup()}return}document.body.classList.add('authenticated');document.body.classList.remove('auth-required');if(gate){gate.hidden=true;gate.innerHTML=''}generateAlerts();save();const title=pageName(currentPage);$('#page-title').textContent=title;$$('.nav-item[data-page]').forEach(n=>n.classList.toggle('active',n.dataset.page===currentPage));$('#nav-transactions').textContent=state.transactions.length;const pages={dashboard,transactions:()=>transactionPage(false),accounts:accountsPage,cards:cardsPage,budgets:budgetsPage,goals:goalsPage,reports:reportsPage,history:()=>transactionPage(true),settings:settingsPage};$('#content').innerHTML=(pages[currentPage]||dashboard)();$('#notification-dot').style.display=state.notifications.some(n=>!n.read)?'block':'none';if(currentPage==='dashboard')requestAnimationFrame(drawTrend);}
function drawTrend(){const canvas=$('#trend-chart');if(!canvas)return;const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=rect.width,h=rect.height,p={l:38,r:8,t:8,b:25};ctx.clearRect(0,0,w,h);const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);return d.toISOString().slice(0,7)});const values=months.map(m=>txTotals(txForMonth(m)));const max=Math.max(1,...values.map(x=>Math.max(x.income,x.expense)));ctx.font='9px DM Sans';for(let i=0;i<4;i++){const y=p.t+(h-p.t-p.b)*i/3;ctx.strokeStyle='#eef1ee';ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillStyle='#9aa39d';ctx.textAlign='right';ctx.fillText(money(max*(1-i/3)).replace(/\.00/,'').replace('$',''),p.l-6,y+3)}const plotH=h-p.t-p.b,step=(w-p.l-p.r)/months.length,bw=Math.min(15,step*.27);values.forEach((v,i)=>{const x=p.l+step*i+step/2;const a=v.income/max*plotH,b=v.expense/max*plotH;ctx.fillStyle='#3d805e';ctx.beginPath();ctx.roundRect(x-bw-2,p.t+plotH-a,bw,a,3);ctx.fill();ctx.fillStyle='#dfa18d';ctx.beginPath();ctx.roundRect(x+2,p.t+plotH-b,bw,b,3);ctx.fill();ctx.fillStyle='#8d9990';ctx.textAlign='center';ctx.fillText(new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(`${months[i]}-02T12:00:00`)),x,h-5)})}
function modal(title,body,footer=`<button class="button button-secondary" type="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">Salvar</button>`){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><form class="modal" id="active-form"><div class="modal-header"><h2>${title}</h2><button type="button" class="close-modal" data-action="close-modal">×</button></div><div class="modal-body">${body}</div><div class="form-footer">${footer}</div></form></div>`;$('#active-form').addEventListener('submit',e=>{e.preventDefault();submitForm(e.currentTarget)});}
function options(list,selected='',labelFn=x=>x.name,valueFn=x=>x.id,empty=''){return `${empty?`<option value="">${empty}</option>`:''}${list.map(x=>`<option value="${esc(valueFn(x))}" ${valueFn(x)===selected?'selected':''}>${esc(labelFn(x))}</option>`).join('')}`}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span class="field-label">${label}</span><input class="input" name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,name,items,value='',empty=''){return `<label class="field"><span class="field-label">${label}</span><select class="select" name="${name}">${options(items,value,x=>x.label,x=>x.value,empty)}</select></label>`}
function txModal(id='',prefill={}){const t=state.transactions.find(x=>x.id===id)||prefill;editingId=id||null;const cats=categories.map(x=>({label:x[0],value:x[0]}));const accounts=state.accounts.map(a=>({name:a.name,id:a.id})),cards=state.cards.map(a=>({name:a.name,id:a.id}));modal(id?'Editar lançamento':'Novo lançamento',`<div class="form-grid">${field('Descrição','description',t.description||'','text','required maxlength="100"')}${selectField('Tipo','type',[{label:'Despesa',value:'expense'},{label:'Receita',value:'income'}],t.type||'expense')}${selectField('Categoria','category',cats,t.category||'Alimentação')}${field('Valor','amount',t.amount!=null?(t.amount/100).toFixed(2):'','number','required min="0.01" step="0.01"')}${field('Data da transação','date',t.date||todayISO(),'date','required')}${field('Data de vencimento','dueDate',t.dueDate||'','date')}${selectField('Conta relacionada','accountId',accounts,t.accountId||'','Sem conta')}${selectField('Cartão de crédito','cardId',cards,t.cardId||'','Sem cartão')}${selectField('Forma de pagamento','paymentMethod',['Cartão de débito','Cartão de crédito','Dinheiro','Transferência','Débito automático','PIX','Outro'].map(x=>({label:x,value:x})),t.paymentMethod||'Transferência')}${selectField('Status','status',[{label:'Pendente',value:'pending'},{label:'Pago',value:'paid'},{label:'Recebido',value:'received'},{label:'Previsto',value:'forecast'}],t.status||'paid')}${selectField('Recorrência','recurrence',[{label:'Única',value:'one-time'},{label:'Semanal',value:'weekly'},{label:'Mensal',value:'monthly'},{label:'Anual',value:'annual'}],t.recurrence||'one-time')}${selectField('Tipo de despesa','fixed',[{label:'Variável',value:'false'},{label:'Fixa',value:'true'}],String(t.fixed||false))}<label class="field full"><span class="field-label">Observações</span><textarea class="textarea" name="notes" rows="2">${esc(t.notes||'')}</textarea></label><label class="field full"><span><input type="checkbox" name="transfer" ${t.transfer?'checked':''}> Transferência entre minhas contas (não contar como receita/despesa)</span></label></div><p class="field-help">Lançamentos recorrentes são salvos como uma ocorrência, sem gerar duplicações automáticas.</p>`);}
function accountModal(id=''){const a=state.accounts.find(x=>x.id===id)||{};editingId=id||null;modal(id?'Editar conta':'Adicionar conta',`<div class="form-grid">${field('Nome da conta','name',a.name||'','text','required')}${field('Instituição','institution',a.institution||'')}${selectField('Tipo','type',[{label:'Conta corrente',value:'checking'},{label:'Poupança / reserva',value:'savings'},{label:'Dinheiro em espécie',value:'cash'},{label:'Investimentos',value:'investment'}],a.type||'checking')}${field('Saldo inicial / atual','balance',a.balance!=null?(a.balance/100).toFixed(2):'0.00','number','required step="0.01"')}${selectField('Moeda',[{label:'Moeda',value:'currency'}][0].value,[{label:'USD · Dólar',value:'USD'},{label:'BRL · Real',value:'BRL'},{label:'EUR · Euro',value:'EUR'}],a.currency||state.settings.currency)}</div><p class="field-help">Use a mesma moeda da sua moeda principal para totais comparáveis. Conversão cambial automática não está habilitada.</p>`)}
function cardModal(id=''){const c=state.cards.find(x=>x.id===id)||{};editingId=id||null;modal(id?'Editar cartão':'Adicionar cartão',`<div class="form-grid">${field('Nome do cartão','name',c.name||'','text','required')}${field('Instituição financeira','institution',c.institution||'')}${field('Limite total','limit',c.limit!=null?(c.limit/100).toFixed(2):'','number','required min="0.01" step="0.01"')}${field('Dia de fechamento','closingDay',c.closingDay||'22','number','min="1" max="31" required')}${field('Dia de vencimento','dueDay',c.dueDay||'5','number','min="1" max="31" required')}${selectField('Conta de pagamento','paymentAccountId',state.accounts.map(a=>({name:a.name,id:a.id})),c.paymentAccountId||'','Selecione')}${field('Identificação de cor','color',c.color||'#176b4c','color')}</div><p class="field-help">Não informe número completo do cartão nem código de segurança.</p>`)}
function budgetModal(id=''){const b=state.budgets.find(x=>x.id===id)||{};editingId=id||null;modal(id?'Editar orçamento':'Novo orçamento',`<div class="form-grid">${selectField('Categoria','category',categories.map(c=>({label:c[0],value:c[0]})),b.category||'Alimentação')}${field('Limite mensal','limit',b.limit!=null?(b.limit/100).toFixed(2):'','number','required min="0.01" step="0.01"')}</div>`)}
function goalModal(id=''){const g=state.goals.find(x=>x.id===id)||{};editingId=id||null;modal(id?'Editar meta':'Criar meta financeira',`<div class="form-grid">${field('Nome da meta','name',g.name||'','text','required')}${field('Valor desejado','target',g.target!=null?(g.target/100).toFixed(2):'','number','required min="0.01" step="0.01"')}${field('Valor já economizado','saved',g.saved!=null?(g.saved/100).toFixed(2):'0','number','min="0" step="0.01"')}${field('Prazo final','dueDate',g.dueDate||`${new Date().getFullYear()+1}-12-31`,'date','required')}${field('Contribuição mensal planejada','monthlyContribution',g.monthlyContribution!=null?(g.monthlyContribution/100).toFixed(2):'','number','min="0" step="0.01"')}${selectField('Prioridade','priority',['Alta','Média','Baixa'].map(x=>({label:x,value:x})),g.priority||'Média')}${selectField('Conta associada','accountId',state.accounts.map(a=>({name:a.name,id:a.id})),g.accountId||'','Nenhuma')}</div>`)}
function balanceImpact(t,sign){if(!t||!t.accountId||t.transfer||!(t.status==='paid'||t.status==='received'))return;const a=state.accounts.find(x=>x.id===t.accountId);if(a)a.balance+=sign*(t.type==='income'?t.amount:-t.amount)}
function submitForm(form){const f=new FormData(form),v=Object.fromEntries(f.entries());if(form.elements.amount&&Number(v.amount)<=0)return notify('O valor deve ser maior que zero.','error');if(form.elements.limit&&Number(v.limit)<=0)return notify('Informe um limite maior que zero.','error');if(form.elements.target&&Number(v.target)<=0)return notify('Informe um objetivo maior que zero.','error');if(form.elements.type&&v.dueDate&&v.dueDate<v.date)return notify('O vencimento deve ser igual ou posterior à data da transação.','error');let result;
if(form.elements.description){const old=state.transactions.find(t=>t.id===editingId);result={id:editingId||uid(),description:v.description.trim(),amount:cents(v.amount),type:v.type,category:v.category,date:v.date,dueDate:v.dueDate||'',accountId:v.accountId||'',cardId:v.cardId||'',paymentMethod:v.paymentMethod,status:v.status,recurrence:v.recurrence,fixed:v.fixed==='true',notes:v.notes||'',transfer:f.elements.transfer.checked,createdAt:old?.createdAt||Date.now(),updatedAt:editingId?Date.now():undefined};if(old)balanceImpact(old,-1);if(old)state.transactions=state.transactions.map(t=>t.id===editingId?result:t);else state.transactions.unshift(result);balanceImpact(result,1)}
else if(form.elements.institution&&form.elements.name&&form.elements.limit){result={id:editingId||uid(),name:v.name.trim(),institution:v.institution,limit:cents(v.limit),closingDay:Number(v.closingDay),dueDay:Number(v.dueDay),paymentAccountId:v.paymentAccountId||'',color:v.color,active:true};state.cards=editingId?state.cards.map(x=>x.id===editingId?result:x):[...state.cards,result]}
else if(form.elements.institution&&form.elements.name){result={id:editingId||uid(),name:v.name.trim(),institution:v.institution,type:v.type,balance:cents(v.balance),currency:v.currency};state.accounts=editingId?state.accounts.map(x=>x.id===editingId?result:x):[...state.accounts,result]}
else if(form.elements.limit){result={id:editingId||uid(),category:v.category,limit:cents(v.limit)};state.budgets=editingId?state.budgets.map(x=>x.id===editingId?result:x):[...state.budgets,result]}
else if(form.elements.target){result={id:editingId||uid(),name:v.name.trim(),target:cents(v.target),saved:cents(v.saved),dueDate:v.dueDate,monthlyContribution:cents(v.monthlyContribution),priority:v.priority,accountId:v.accountId||''};state.goals=editingId?state.goals.map(x=>x.id===editingId?result:x):[...state.goals,result]}
else if(form.dataset.import==='true'){const rows=state._importRows||[];let added=0;for(const row of rows){const amount=cents(row.amount);if(!row.description||!row.date||amount<=0)continue;const dup=state.transactions.some(t=>t.date===row.date&&t.amount===amount&&t.description.toLowerCase()===row.description.toLowerCase());if(dup)continue;state.transactions.unshift({id:uid(),description:row.description,amount,type:row.type||'expense',category:row.category||'Outros',date:row.date,accountId:'',paymentMethod:'Importação CSV',status:'paid',recurrence:'one-time',fixed:false,createdAt:Date.now()});added++}delete state._importRows;state.isDemo=false;closeModal();save();notify(`${added} lançamento(s) importado(s).`);render();return}
else return;state.isDemo=false;closeModal();save();notify(editingId?'Alterações salvas.':'Item adicionado.');render()}
function closeModal(){$('#modal-root').innerHTML='';editingId=null}
function deleteBy(type,id){const map={tx:['transactions','lançamento'],budget:['budgets','orçamento'],goal:['goals','meta']},[field,label]=map[type]||[];if(!field)return;const item=state[field].find(x=>x.id===id);if(!item)return;if(!confirm(`Excluir ${label} “${item.description||item.category||item.name}”? Esta ação não pode ser desfeita.`))return;if(type==='tx')balanceImpact(item,-1);state[field]=state[field].filter(x=>x.id!==id);state.isDemo=false;save();notify('Registro excluído.');render()}
function exportCsv(list=state.transactions,name='transacoes'){const head=['descricao','valor','tipo','categoria','data','vencimento','conta','cartao','forma_pagamento','status','recorrencia','observacoes'];const rows=list.map(t=>[t.description,(t.amount/100).toFixed(2),t.type,t.category,t.date,t.dueDate||'',state.accounts.find(a=>a.id===t.accountId)?.name||'',state.cards.find(c=>c.id===t.cardId)?.name||'',t.paymentMethod||'',t.status,t.recurrence||'',t.notes||'']);const csv=[head,...rows].map(r=>r.map(x=>`"${String(x??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');download(csv,`${name}-${todayISO()}.csv`,'text/csv;charset=utf-8');notify('Arquivo CSV exportado.')}
function download(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importCsv(){const inp=document.createElement('input');inp.type='file';inp.accept='.csv,text/csv';inp.onchange=async()=>{const file=inp.files[0];if(!file)return;const text=await file.text();const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(lines.length<2)return notify('O CSV não contém linhas de dados.','error');const parse=line=>{const out=[];let cur='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&quoted){cur+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cur);cur=''}else cur+=c}out.push(cur);return out};const headers=parse(lines[0]).map(x=>x.trim().toLowerCase().replace(/\s+/g,'_'));const idx=key=>headers.findIndex(x=>x.includes(key));const di=idx('descr'),ai=idx('valor'),ti=idx('data'),ci=idx('categori'),ty=idx('tipo');if(di<0||ai<0||ti<0)return notify('CSV precisa conter colunas descrição, valor e data.','error');const rows=lines.slice(1).map(line=>{const c=parse(line),date=normalizeDate(c[ti]);return {description:c[di],amount:Number(String(c[ai]).replace(/[$\s]/g,'').replace(',','.')),date,category:ci>=0?c[ci]:'Outros',type:ty>=0&&/receita|income/i.test(c[ty])?'income':'expense'}}).filter(x=>x.description&&x.date&&Number.isFinite(x.amount));const dup=rows.filter(r=>state.transactions.some(t=>t.date===r.date&&t.amount===cents(r.amount)&&t.description.toLowerCase()===r.description.toLowerCase())).length;state._importRows=rows;modal('Revisar importação CSV',`<p class="muted">${rows.length} linha(s) válidas · ${dup} possível(is) duplicação(ões), que serão ignoradas ao salvar.</p><div class="import-preview"><table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Valor</th></tr></thead><tbody>${rows.slice(0,50).map(r=>`<tr><td>${formatDate(r.date)}</td><td>${esc(r.description)}</td><td>${esc(r.category)}</td><td>${money(cents(r.amount))}</td></tr>`).join('')}</tbody></table></div><p class="field-help">Revise a prévia antes de confirmar. Importações aceitam CSV separado por vírgulas, com descrição, valor e data.</p>`);$('#active-form').dataset.import='true';$('#active-form').querySelector('[type=submit]').textContent='Confirmar e importar'};inp.click()}
function normalizeDate(d){if(!d)return '';d=d.trim();if(/^\d{4}-\d\d-\d\d$/.test(d))return d;const m=d.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);if(m){let a=Number(m[1]),b=Number(m[2]);if(a>12)[a,b]=[b,a];return `${m[3]}-${String(b).padStart(2,'0')}-${String(a).padStart(2,'0')}`}return ''}
function showNotifications(){const old=$('.notice-center');if(old){old.remove();return}const wrap=document.createElement('div');wrap.className='notice-center';wrap.innerHTML=`<h3>Notificações <button class="inline-action" style="float:right" data-action="mark-read">Marcar como lidas</button></h3>${state.notifications.length?state.notifications.slice(0,12).map(n=>`<div class="notice-item"><b>${esc(n.title)}</b><br>${esc(n.body)}<small>${formatDate(n.date)} · ${n.priority==='high'?'Prioridade alta':'Aviso'}</small></div>`).join(''):'<div class="notice-item">Tudo em dia por aqui. Seus alertas aparecerão nesta lista.</div>'}`;document.body.append(wrap)}
function exportBackup(){download(JSON.stringify(state,null,2),`horizonte-backup-${todayISO()}.json`,'application/json');notify('Cópia de segurança exportada.')}
function restoreBackup(){const inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.onchange=async()=>{try{const obj=JSON.parse(await inp.files[0].text());if(!obj.accounts||!obj.transactions||!obj.settings)throw Error();if(!confirm('Substituir os dados atuais pelo backup selecionado?'))return;state=obj;save();render();notify('Dados restaurados.')}catch{notify('Arquivo de backup inválido.','error')}};inp.click()}
function recordPayment(t){if(t.status==='pending'||t.status==='forecast'){t.status=t.type==='income'?'received':'paid';balanceImpact(t,1);state.isDemo=false;save();render();notify(t.type==='income'?'Recebimento registrado.':'Pagamento registrado.')}}
function action(action,id){switch(action){case'new-tx':txModal();break;case'edit-tx':txModal(id);break;case'delete-tx':deleteBy('tx',id);break;case'new-account':accountModal();break;case'edit-account':accountModal(id);break;case'account-history':currentPage='transactions';txQuery=state.accounts.find(x=>x.id===id)?.name||'';txQuery='';txType='all';render();break;case'new-card':cardModal();break;case'edit-card':cardModal(id);break;case'new-card-purchase':txModal('',{type:'expense',cardId:id,paymentMethod:'Cartão de crédito',status:'paid',date:todayISO()});break;case'new-budget':budgetModal();break;case'edit-budget':budgetModal(id);break;case'delete-budget':deleteBy('budget',id);break;case'new-goal':goalModal();break;case'edit-goal':goalModal(id);break;case'delete-goal':deleteBy('goal',id);break;case'contribute-goal':{const g=state.goals.find(x=>x.id===id),amount=prompt(`Quanto deseja adicionar à meta “${g.name}”?`,(g.monthlyContribution/100).toFixed(2));if(amount!==null&&Number(amount)>0){g.saved+=cents(amount);if(g.accountId){const a=state.accounts.find(x=>x.id===g.accountId);if(a)a.balance+=cents(amount)}state.isDemo=false;save();render();notify('Contribuição registrada.')}break}case'import-csv':importCsv();break;case'export-csv':exportCsv();break;case'export-report':exportCsv(state.transactions.filter(t=>isoMonth(t.date)===selectedMonth()),'relatorio-mensal');break;case'backup':exportBackup();break;case'restore':restoreBackup();break;case'close-modal':closeModal();break;case'clear-demo':if(confirm('Remover todos os exemplos e começar com dados vazios?')){state=initialState();state.isDemo=false;state.accounts=[];state.cards=[];state.transactions=[];state.budgets=[];state.goals=[];state.notifications=[];save();render();notify('Demonstração limpa.')}break;case'mark-read':state.notifications.forEach(n=>n.read=true);save();$('.notice-center')?.remove();$('#notification-dot').style.display='none';notify('Notificações marcadas como lidas.');break;}}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){e.preventDefault();currentPage=page.dataset.page;$('#sidebar').classList.remove('open');render();return}const el=e.target.closest('[data-action]');if(el){if(el.dataset.action==='backdrop'&&e.target!==el)return;action(el.dataset.action,el.dataset.id)}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action="settle-tx"]');if(el){const t=state.transactions.find(x=>x.id===el.dataset.id);if(t)recordPayment(t)}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action="supabase-test"],[data-action="supabase-login"],[data-action="supabase-signup"],[data-action="supabase-logout"],[data-action="auth-forgot"],[data-action="auth-back"],[data-action="supabase-send-reset"],[data-action="supabase-update-password"]');if(!el)return;if(el.dataset.action==='supabase-test')testSupabaseConnection();if(el.dataset.action==='supabase-login')authenticateSupabase('login');if(el.dataset.action==='supabase-signup')authenticateSupabase('signup');if(el.dataset.action==='supabase-logout')signOutSupabase();if(el.dataset.action==='auth-forgot'){authEmailDraft=$('#supabase-email')?.value.trim()||authEmailDraft;authView='recovery';authMessage='';render()}if(el.dataset.action==='auth-back'){authView='login';authMessage='';render()}if(el.dataset.action==='supabase-send-reset')requestPasswordReset();if(el.dataset.action==='supabase-update-password')updateRecoveredPassword()});
$('#quick-add').addEventListener('click',()=>txModal());$('#notification-button').addEventListener('click',showNotifications);$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
document.addEventListener('input',e=>{if(e.target.id==='tx-search'){txQuery=e.target.value;const pos=e.target.selectionStart;render();const input=$('#tx-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='supabase-email')authEmailDraft=e.target.value});
document.addEventListener('change',async e=>{if(e.target.id==='month-filter'){render();return}if(e.target.id==='tx-type'){txType=e.target.value;render()}if(e.target.id==='tx-status'){txStatus=e.target.value;render()}if(e.target.id==='tx-sort'){txSort=e.target.value;render()}if(e.target.id==='settings-currency'){state.settings.currency=e.target.value;save();render();await persistSpaceSettings()}if(e.target.id==='settings-date'){state.settings.dateFormat=e.target.value;save();render();await persistSpaceSettings()}});
document.addEventListener('change',async e=>{if(e.target.id==='supabase-space-select'){selectedSpaceId=e.target.value;state.settings={currency:'USD',dateFormat:'MM/DD/YYYY'};save();await loadSpaceSettings();render();const name=supabaseMemberships.find(m=>m.space_id===selectedSpaceId)?.space_name;notify(`Preferências carregadas para ${name||selectedSpaceId}.`)}});
window.addEventListener('resize',()=>{if(currentPage==='dashboard')drawTrend()});
render();
window.supabaseClient?.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){authView='update-password';authMessage='';supabaseUser=session?.user||null;render()}});
restoreSupabaseSession();
